function byName() {
  const m = new Map();
  for (const ins of INSTRUCTIONS) {
    const k = ins.name.toLowerCase();
    if (!m.has(k)) m.set(k, []);
    m.get(k).push(ins);
  }
  // fewer operands first, helps variant selection
  for (const arr of m.values()) arr.sort((a, b) => a.order.length - b.order.length);
  return m;
}

module.exports = { TYPES, INSTRUCTIONS, byName };